const SquadUI=(()=>{
  let model,legacy,roster,drag=null,suppressClick=false,guideTimer=null,removedTemplate=null,previewChanged=false;
  const key='unit-fc-squads-v1';
  const names={ST:'스트라이커',CF:'중앙 공격수',LW:'왼쪽 윙어',RW:'오른쪽 윙어',CAM:'공격형 미드필더',CM:'중앙 미드필더',LM:'왼쪽 미드필더',RM:'오른쪽 미드필더',CDM:'수비형 미드필더',CB:'센터백',LB:'왼쪽 풀백',RB:'오른쪽 풀백',LWB:'왼쪽 윙백',RWB:'오른쪽 윙백',GK:'골키퍼'};
  function init(list,state){roster=list;legacy=state;let stored;try{stored=JSON.parse(TeamStore.getItem(key));}catch{}model=SquadLayout.create(list,state,stored);sync();}
  function refresh(){if(drag){drag.el.classList.remove('dragging');drag=null;}clearGuides();model=SquadLayout.create(roster,legacy,model.book);sync();}
  function sync(){legacy.lineup=model.current().slots.map(p=>p.id);legacy.formation=model.current().formation==='custom'?'자유 배치':model.current().formation;}
  function isPreview(){return window.TeamSync&&!TeamSync.canEdit;}
  function persist(announce=false){sync();if(isPreview()){previewChanged=true;return true;}try{TeamStore.setItem(key,JSON.stringify(model.book));if(announce)toast(`${model.book.size}인제 스쿼드를 저장했습니다.`);return true;}catch{toast('저장 공간을 사용할 수 없습니다. 이번 방문에만 유지됩니다.');return false;}}
  function change(action){try{action();persist();render();}catch(error){toast(error.message);}}
  function pitch(big=false){const s=model.current(),size=model.book.size,free=s.formation==='custom';return `<div class="pitch squad-pitch ${big?'big-pitch editable-pitch':''} ${big&&free?'free-pitch':''}" data-squad-size="${size}"><div class="pitch-lines"><div class="penalty top"></div><div class="penalty bottom"></div></div>${big&&free?zoneOverlay():''}<div class="snap-guides" aria-hidden="true"></div><span class="formation-chip">${esc(model.title())} <span>· ${size}인제</span></span>${s.slots.map((slot,i)=>{const p=roster.find(p=>p.id===slot.id);return `<button class="pitch-player" style="left:${slot.x}%;top:${slot.y}%" data-action="${big?'squad-slot':'player'}" data-slot="${i}" data-id="${p.id}" aria-label="${p.name} ${slot.pos} ${big?'위치·포지션 편집':'상세 보기'}" ${big&&free?'aria-describedby="squad-drag-help"':''}><span class="shirt ${slot.pos==='GK'?'gk':''}" aria-hidden="true">${slot.pos}</span><b><span>${Abilities.positionRating(p,slot.pos)??'—'}</span>${p.name}</b></button>`;}).join('')}</div>`;}
  function zoneOverlay(){const b=SquadLayout.zoneBounds;return `<div class="position-zones" aria-hidden="true"><i class="zone-border horizontal" style="top:${b.attack}%"></i><i class="zone-border horizontal" style="top:${b.defense}%"></i><i class="zone-border vertical" style="left:${b.left}%"></i><i class="zone-border vertical" style="left:${b.right}%"></i><span class="zone-band" style="top:16%">공격</span><span class="zone-band" style="top:46%">중원</span><span class="zone-band" style="top:73%">수비</span><strong class="zone-preview"></strong></div>`;}
  function page(){const size=model.book.size,s=model.current(),free=s.formation==='custom';return `${head('스쿼드','경기 인원에 맞게 배치하세요. OVR은 배치 포지션 기준입니다.',btn('스쿼드 저장','squad-save','','squad'),'BUILD YOUR TEAM')}${squadModes('squad')}${isPreview()?'<p class="note squad-preview-note">포메이션 미리보기 · 변경한 배치는 이 화면에서만 적용됩니다.</p>':''}<section class="squad-controls"><h2>경기 인원 <small>골키퍼 자리 1개 포함</small></h2><div class="squad-sizes" role="group" aria-label="경기 인원">${[4,5,6,7].map(n=>`<button data-action="squad-size" data-value="${n}" aria-pressed="${size===n}">${n}<small>인제</small></button>`).join('')}</div><div class="squad-formation-label"><strong>포메이션</strong><span>숫자는 필드 선수 수입니다</span></div><div class="squad-formations" role="group" aria-label="포메이션">${[...Object.keys(SquadLayout.presets[size]),'custom'].map(f=>`<button data-action="squad-formation" data-value="${f}" aria-pressed="${s.formation===f}">${f==='custom'?'자유 배치':f}</button>`).join('')}</div><p class="squad-help">${free?'선수를 끌어 위치를 조정하거나, 눌러서 포지션과 선수를 변경하세요.':'기본 포메이션을 선택하면 위치·포지션이 재설정됩니다. 선수는 눌러서 편집하세요.'}</p>${free?`<div class="squad-free-tools"><button data-action="squad-snap-toggle" aria-pressed="${model.book.snapEnabled}">⊞ 자동 정렬 ${model.book.snapEnabled?'켜짐':'꺼짐'}</button><button data-action="squad-template-save">이름 붙여 저장</button></div><p class="squad-snap-help">가로·세로 줄과 중앙에 가까워지면 자동으로 맞춥니다. 구역을 넘으면 포지션이 바뀌며, 선수를 눌러 세부 포지션을 선택할 수 있습니다.</p>`:''}<div class="squad-tools"><button class="btn secondary" data-action="squad-best">OVR순 선발</button><button class="btn ghost" data-action="squad-random">랜덤 선발</button></div>${templateLibrary()}</section><section class="panel">${panelhead('선발 라인업',`${size} PLAYERS`,`<span class="tag">${ClubSettings.html('name')}</span>`)}${pitch(true)}<div class="pitch-footer"><span id="squad-drag-help">${free?'정렬선에 맞춰 이동 · 방향키로 미세 조정':'자유 배치를 선택하면 직접 이동할 수 있어요'}</span><strong>${size-1} 필드 + 1 GK</strong></div></section><p class="squad-position-status" role="status" aria-live="polite"></p>${roster.some(p=>p.pos==='GK')?'':'<p class="note">등록된 골키퍼가 없어 GK 자리에 임시로 선수를 배치했습니다. 선수를 눌러 담당자를 지정하세요.</p>'}<p class="squad-save-note">${isPreview()?'새로고침하면 팀에 저장된 배치로 돌아갑니다.':'관리자가 저장한 인원별 배치를 팀원들과 공유합니다.'}</p><section class="panel">${panelhead('교체 선수','ON THE BENCH')}<div class="panel-body">${roster.filter(p=>!s.slots.some(x=>x.id===p.id)).map(p=>`<div class="bench-row"><div><strong>${p.name}</strong><small>${p.pos} · ${p.role}</small></div><span class="overall">${p.ovr??'—'}</span><button data-action="squad-sub" data-id="${p.id}">투입</button></div>`).join('')}</div></section>`;}
  function templateLibrary(){return `<details class="squad-templates" ${removedTemplate?'open':''}><summary>저장한 포메이션 <b>${model.book.templates.length}</b></summary><p>이름을 누르면 해당 인원과 배치를 불러옵니다. 선수 명단은 유지됩니다.</p>${model.book.templates.length?model.book.templates.map(t=>`<div class="squad-template-row"><button class="squad-template-load" data-action="squad-template-load" data-template-id="${esc(t.id)}"><span>${t.size}인제</span><strong>${esc(t.name)}</strong><small>${model.current().templateId===t.id?'적용 중':'불러오기'}</small></button><div><button data-action="squad-template-update" data-template-id="${esc(t.id)}" ${t.size!==model.book.size?'disabled':''}>현재 배치로 갱신</button><button data-action="squad-template-delete" data-template-id="${esc(t.id)}" aria-label="${esc(t.name)} 삭제">삭제</button></div></div>`).join(''):`<div class="squad-template-empty">${isPreview()?'아직 저장한 포메이션이 없습니다.':'자유 배치에서 ‘이름 붙여 저장’을 눌러 보세요.'}</div>`}${removedTemplate?`<div class="squad-template-undo"><span>‘${esc(removedTemplate.name)}’ 삭제됨</span><button data-action="squad-template-undo">되돌리기</button></div>`:''}</details>`;}
  function templateSaveModal(replaceId){const existing=model.book.templates.find(t=>t.id===replaceId);if($('#modal').open)closeModal();modal(existing?'저장한 포메이션 갱신':'포메이션 이름 붙여 저장',`<form id="squad-template-form" data-replace-id="${existing?esc(existing.id):''}"><span class="tag">${model.book.size}인제 · 자유 배치</span><label class="field" style="margin-top:22px">포메이션 이름<input name="name" aria-label="포메이션 이름" maxlength="32" required placeholder="예: 빠른 역습형" value="${existing?esc(existing.name):''}" autocomplete="off"></label><p class="note">${existing?'이 포메이션을 현재 피치의 위치와 포지션으로 갱신합니다.':'현재 피치의 위치와 포지션을 저장합니다.'}<br>선수 명단은 저장하지 않아 다른 라인업에도 사용할 수 있습니다.</p><p id="squad-template-error" class="form-error" role="alert"></p><p class="prototype-note">저장한 포메이션을 다른 기기에서도 불러올 수 있습니다.</p><div class="modal-actions"><button type="button" class="btn secondary" data-action="close">취소</button><button class="btn" type="submit">${existing?'현재 배치로 갱신':'포메이션 저장'}</button></div></form>`);}
  function templateChange(action){const before=JSON.parse(JSON.stringify(model.book));try{action();if(!persist()){model=SquadLayout.create(roster,legacy,before);sync();return false;}return true;}catch(error){model=SquadLayout.create(roster,legacy,before);sync();throw error;}}
  function slotModal(index,incoming){const slot=model.current().slots[index],isGK=index===model.book.size-1,p=roster.find(p=>p.id===(incoming||slot.id));if(!slot||!p)return;if($('#modal').open)closeModal();modal('선수 · 포지션 편집',`<form id="squad-slot-form" data-slot="${index}"><p class="note">${model.book.size}인제 · ${isGK?'골키퍼 자리':'필드 선수 자리'}<br>선발 선수를 선택하면 두 선수의 자리가 교환됩니다.</p><label class="field">배치 선수<select name="player" aria-label="배치 선수">${roster.filter(p=>isGK?(roster.some(p=>p.pos==='GK')?p.pos==='GK':true):p.pos!=='GK').map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${x.name} · ${x.pos}${model.current().slots.some(s=>s.id===x.id)?' · 선발':''}</option>`).join('')}</select></label><div class="squad-zone-info"><strong>${SquadLayout.zoneAt(slot.x,slot.y,isGK).name} 구역</strong><span>${isGK?'골키퍼 자리는 GK로 유지됩니다.':'현재 위치에서 가능한 세부 포지션만 선택할 수 있습니다.'}</span></div><label class="field">세부 포지션<select name="position" aria-label="배치 포지션">${SquadLayout.zoneAt(slot.x,slot.y,isGK).positions.map(pos=>`<option value="${pos}" ${pos===slot.pos?'selected':''}>${pos} · ${names[pos]}</option>`).join('')}</select></label><p class="note">포지션을 변경하면 자유 배치로 전환됩니다. 위치는 피치에서 선수를 끌어 조정하세요.</p><div class="modal-actions"><button type="button" class="btn secondary" data-action="close">취소</button><button class="btn" type="submit">배치 적용</button></div></form>`);}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!model)return;const a=b.dataset.action;if(a==='squad-slot'){if(suppressClick){suppressClick=false;return;}slotModal(Number(b.dataset.slot));}else if(a==='squad-size')change(()=>model.setSize(Number(b.dataset.value)));else if(a==='squad-formation')change(()=>model.setFormation(b.dataset.value));else if(a==='squad-best'||a==='squad-random')change(()=>model.arrange(a==='squad-best'?'best':'random'));else if(a==='squad-save')persist(true);else if(a==='squad-sub'){const p=roster.find(p=>p.id===Number(b.dataset.id));modal('교체할 선수 선택',`<p class="note">${p.name} 선수를 투입할 자리를 선택하세요.</p>${model.current().slots.map((s,i)=>({s,i})).filter(({s})=>!roster.some(x=>x.pos==='GK')||(s.pos==='GK')===(p.pos==='GK')).map(({s,i})=>`<button class="squad-swap-choice" data-action="squad-sub-slot" data-slot="${i}" data-id="${p.id}"><strong>${roster.find(x=>x.id===s.id).name}</strong><span>${s.pos} <svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></span></button>`).join('')}`);}else if(a==='squad-sub-slot')slotModal(Number(b.dataset.slot),Number(b.dataset.id));});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!model)return;const a=b.dataset.action,id=b.dataset.templateId;
    if(a==='squad-snap-toggle')change(()=>{model.book.snapEnabled=!model.book.snapEnabled;});
    else if(a==='squad-template-save')templateSaveModal();
    else if(a==='squad-template-update')templateSaveModal(id);
    else if(a==='squad-template-load'){change(()=>model.loadTemplate(id));}
    else if(a==='squad-template-delete'){try{let deleted;if(templateChange(()=>{deleted=model.removeTemplate(id);})){removedTemplate=deleted;render();}}catch(error){toast(error.message);}}
    else if(a==='squad-template-undo'){try{if(templateChange(()=>model.restoreTemplate(removedTemplate))){removedTemplate=null;render();}}catch(error){toast(error.message);}}
  });
  document.addEventListener('submit',e=>{if(e.target.id!=='squad-template-form')return;e.preventDefault();const form=e.target,data=new FormData(form);try{const existing=form.dataset.replaceId||undefined;if(!templateChange(()=>model.saveTemplate(crypto.randomUUID(),data.get('name'),existing))){$('#squad-template-error').textContent='저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.';return;}closeModal();render();toast('포메이션을 이름과 함께 저장했습니다.');}catch(error){$('#squad-template-error').textContent=error.message;}});
  document.addEventListener('submit',e=>{if(e.target.id!=='squad-slot-form')return;e.preventDefault();const data=new FormData(e.target),index=Number(e.target.dataset.slot),slot=model.current().slots[index];model.edit(index,{id:Number(data.get('player')),pos:data.get('position'),x:slot.x,y:slot.y});closeModal();persist();render();});
  function refreshFormationLabels(pitch){pitch.querySelector('.formation-chip').innerHTML=esc(model.title())+' <span>· '+model.book.size+'인제</span>';document.querySelectorAll('.squad-template-load').forEach(el=>{el.querySelector('small').textContent=el.dataset.templateId===model.current().templateId?'적용 중':'불러오기';});}
  function clearGuides(){clearTimeout(guideTimer);document.querySelectorAll('.snap-guides').forEach(el=>el.replaceChildren());document.querySelectorAll('.snap-target').forEach(el=>el.classList.remove('snap-target'));}
  function showGuides(pitch,result,index){clearGuides();const guides=pitch.querySelector('.snap-guides');guides.innerHTML=Object.entries(result.guides).map(([axis,g])=>`<div class="snap-line snap-line-${axis}" style="${axis==='x'?'left':'top'}:${g.value}%"><span>${g.center?(axis==='x'?'세로 중앙':'가로 중앙'):(axis==='x'?'세로 정렬':'가로 정렬')}</span></div>`).join('');model.current().slots.forEach((s,i)=>{if(i!==index&&((result.guides.x&&Math.abs(s.x-result.x)<.01)||(result.guides.y&&Math.abs(s.y-result.y)<.01)))pitch.querySelector('[data-slot="'+i+'"]').classList.add('snap-target');});}
  function refreshPlayerLabel(el,pos){const p=roster.find(p=>p.id===Number(el.dataset.id));el.querySelector('.shirt').textContent=pos;el.querySelector('b>span').textContent=Abilities.positionRating(p,pos)??'—';el.setAttribute('aria-label',p.name+' '+pos+' 위치·포지션 편집');}
  function announcePosition(index,previous){const slot=model.current().slots[index];const status=$('.squad-position-status');if(status)status.textContent=slot.pos!==previous?roster.find(p=>p.id===slot.id).name+' · '+SquadLayout.zoneAt(slot.x,slot.y,index===model.book.size-1).name+' → '+slot.pos+' · 눌러서 세부 포지션 선택':'';}
  function move(index,x,y){const slot=model.current().slots[index];model.edit(index,{...slot,x,y});}
  document.addEventListener('pointerdown',e=>{const el=e.target.closest('.free-pitch .pitch-player');if(!el||!e.isPrimary||e.button!==0)return;suppressClick=false;clearGuides();const rect=el.closest('.pitch').getBoundingClientRect();drag={el,index:Number(el.dataset.slot),pointer:e.pointerId,startX:e.clientX,startY:e.clientY,rect,slot:{...model.current().slots[Number(el.dataset.slot)]},moved:false};el.setPointerCapture(e.pointerId);});
  document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointer)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(!drag.moved&&Math.hypot(dx,dy)<5)return;drag.moved=true;drag.el.classList.add('dragging');const x=Math.max(12,Math.min(88,drag.slot.x+dx/drag.rect.width*100)),y=Math.max(14,Math.min(88,drag.slot.y+dy/drag.rect.height*100));const result=SquadLayout.snap(model.current().slots,drag.index,x,y,drag.rect.width,drag.rect.height,model.book.snapEnabled&&!e.altKey,e.pointerType==='touch'?12:9);drag.x=result.x;drag.y=result.y;drag.el.style.left=result.x+'%';drag.el.style.top=result.y+'%';const pitch=drag.el.closest('.pitch'),keeper=drag.index===model.book.size-1,preview=SquadLayout.positionAt(drag.slot,result.x,result.y,keeper);refreshPlayerLabel(drag.el,preview);pitch.classList.toggle('show-position-zones',!keeper);pitch.querySelector('.zone-preview').textContent=SquadLayout.zoneAt(result.x,result.y,keeper).name+' · '+preview;showGuides(drag.el.closest('.pitch'),result,drag.index);});
  function finish(e){if(!drag||e.pointerId!==drag.pointer)return;const d=drag;drag=null;d.el.classList.remove('dragging');d.el.closest('.pitch').classList.remove('show-position-zones');if(d.moved&&e.type!=='pointercancel'){move(d.index,d.x,d.y);refreshPlayerLabel(d.el,model.current().slots[d.index].pos);announcePosition(d.index,d.slot.pos);persist();refreshFormationLabels(d.el.closest('.pitch'));guideTimer=setTimeout(clearGuides,750);suppressClick=true;setTimeout(()=>{suppressClick=false;},0);}else{clearGuides();d.el.style.left=d.slot.x+'%';d.el.style.top=d.slot.y+'%';refreshPlayerLabel(d.el,d.slot.pos);}}
  document.addEventListener('pointerup',finish);document.addEventListener('pointercancel',finish);
  document.addEventListener('keydown',e=>{const el=e.target.closest('.free-pitch .pitch-player');if(!el||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();clearGuides();const index=Number(el.dataset.slot),s=model.current().slots[index],step=e.shiftKey?5:1,previous=s.pos;move(index,s.x+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),s.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0));const next=model.current().slots[index];el.style.left=next.x+'%';el.style.top=next.y+'%';refreshPlayerLabel(el,next.pos);announcePosition(index,previous);persist();refreshFormationLabels(el.closest('.pitch'));});
  return {init,refresh,pitch,page,slotModal,get previewChanged(){return previewChanged;}};
})();
